-- Questões originais de estudo baseadas em Date, tradução da 8ª edição (2004).
-- Não são questões oficiais do CP-T nem exercícios transcritos do livro.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens são rascunhos: revise no painel antes de publicar.
-- Páginas referem-se ao arquivo PDF fornecido, não à paginação impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve os registros deste lote.
-- As explicações acompanham o contexto histórico da edição, quando pertinente.
-- Capítulo 25: Bancos de dados de objetos — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('f9aa5560-52bb-5083-9ff6-561058440c3b', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Na correspondência terminológica proposta por Date, objetos imutáveis aproximam-se de:', '["Sessões.","Valores.","Índices físicos.","Logs.","Variáveis atualizáveis."]'::jsonb, 1, 'O autor distingue valores imutáveis de variáveis que podem assumir valores diferentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.2, páginas 1294–1299 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ab703467-3c9e-5977-a185-da2ca3926f24', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Objetos mutáveis aproximam-se, na terminologia tradicional usada pelo autor, de:', '["Variáveis.","Somente strings imutáveis.","Apenas funções booleanas.","Tipos sem instâncias.","Constantes matemáticas."]'::jsonb, 0, 'A possibilidade de alterar estado corresponde à noção de variável.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.2, páginas 1294–1299 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d593ceeb-b7ec-5d64-991f-03951a97e20e', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Fácil', 'Encapsular um objeto significa principalmente:', '["Proibir qualquer operação de leitura.","Controlar seu acesso por uma interface, ocultando detalhes de representação.","Expor todos os endereços internos.","Copiar o objeto para cada usuário.","Transformar toda variável em constante."]'::jsonb, 1, 'A interface permite usar o objeto sem depender de sua implementação interna.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.2, páginas 1294–1299 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('63745ed4-4372-576c-a845-30c303cefc9a', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Médio', 'Alterar a representação interna preservando métodos e contratos públicos favorece:', '["Ausência de qualquer abstração.","Independência das aplicações em relação à implementação.","Dependência de ponteiros físicos.","Eliminação de todos os tipos.","Obrigação de reescrever cada cliente."]'::jsonb, 1, 'O encapsulamento protege consumidores quando a interface permanece compatível.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.2, páginas 1294–1299 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('90378e5b-0a23-50e6-8756-28ecdad08c6f', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Fácil', 'Um método é comparado no capítulo a:', '["Um operador aplicável aos objetos correspondentes.","Um índice obrigatório.","Uma página física.","Uma chave estrangeira por definição.","Uma cópia de backup."]'::jsonb, 0, 'Métodos descrevem operações; dados e operações não devem ser confundidos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.2, páginas 1294–1299 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1880d781-044f-5411-8e70-64ee5fe6da51', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'Enviar uma mensagem a um objeto corresponde, essencialmente, a:', '["Alterar a chave primária.","Criar um esquema externo.","Confirmar uma transação.","Invocar uma operação com um destinatário destacado.","Copiar todo o banco pela rede necessariamente."]'::jsonb, 3, 'Mensagem, nesse contexto, é um conceito de invocação, não necessariamente de transporte em rede.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.2, páginas 1294–1299 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('91a49ec9-34a4-57fb-bfe6-dc927d3820c6', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'Uma classe e a coleção atual de suas instâncias são conceitos idênticos?', '["Sim, se houver um único método.","Sim, somente em bancos persistentes.","Não, porque classes não podem ter instâncias.","Não; é preciso distinguir definição de tipo e coleção de objetos.","Sim, toda classe é apenas seu conteúdo atual."]'::jsonb, 3, 'A confusão entre tipo e coleção reaparece na crítica relacional/objeto do capítulo seguinte.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.2, páginas 1294–1299 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('cb31f6c1-42cd-5d37-a12f-e678823ee11e', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Fácil', 'Qual é a finalidade de uma identidade de objeto, OID?', '["Confirmar suas alterações.","Somar seus atributos numéricos.","Distinguir e referenciar um objeto independentemente de seus atributos de negócio.","Validar automaticamente regras do domínio.","Ordenar todos os nomes."]'::jsonb, 2, 'Identidade do objeto e valores de suas propriedades são noções diferentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.3, páginas 1300–1311 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d57eeec4-7e50-5724-89d8-93cb145cf286', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Dois objetos possuem atributos de negócio iguais. Isso implica necessariamente a mesma identidade?', '["Sim, caso existam métodos.","Sim, se os atributos forem texto.","Sim, sempre.","Não, porque objetos nunca possuem atributos.","Não, em um sistema com identidade de objetos."]'::jsonb, 4, 'A igualdade do estado observado não exige identidade do objeto.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.3, páginas 1300–1311 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('01612ac2-6794-54f0-acb9-72e6a247ea04', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Se um objeto altera seu nome e mantém a mesma OID, isso ilustra:', '["Ausência de referência.","Mudança obrigatória de identidade.","Criação automática de outro tipo.","Persistência da identidade apesar de mudança de estado.","Imutabilidade do objeto."]'::jsonb, 3, 'A identidade não precisa ser calculada a partir do nome de negócio.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.3, páginas 1300–1311 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('22a6617d-e205-53ac-a16e-764d5d410d18', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Expor diretamente variáveis internas de um objeto pode enfraquecer:', '["O número de usuários.","A ordenação de nomes de classes.","O encapsulamento da representação.","A possibilidade de ter métodos.","A existência de qualquer valor."]'::jsonb, 2, 'Clientes podem tornar-se dependentes de detalhes que deveriam permanecer internos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.3, páginas 1300–1311 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a9bc25ea-e68a-5436-9076-180212dcab4a', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Referências entre objetos permitem representar:', '["Apenas tabelas sem tipo.","Sempre relacionamentos um para um.","Exclusivamente restrições de acesso.","Somente valores sem identidade.","Associações navegáveis entre suas instâncias."]'::jsonb, 4, 'A cardinalidade e a integridade dessas associações ainda precisam ser especificadas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.3, páginas 1300–1311 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('866b6c17-e56d-581b-9707-620dda816e1b', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'A existência de referências a objetos garante automaticamente qualquer regra de exclusão do domínio?', '["Não; é preciso definir e implementar a política apropriada.","Sim, se os nomes forem únicos.","Não, porque objetos não podem ser excluídos em nenhum sistema.","Sim, referências implementam toda regra de negócio.","Sim, desde que haja uma OID."]'::jsonb, 0, 'Gerenciamento de referências não equivale a um conjunto completo de restrições declarativas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.4, páginas 1312–1325 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fc09ed4f-ff72-5a6d-9fd0-828681e7c3c7', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Excluir um objeto pai deve necessariamente excluir todos os objetos que ele referencia?', '["Sim, qualquer referência implica propriedade exclusiva.","Não; propriedade, compartilhamento e regras de exclusão precisam ser considerados.","Sim, inclusive objetos compartilhados por outros pais.","Não, porque exclusões são proibidas.","Sim, em todos os modelos de objetos."]'::jsonb, 1, 'Uma associação por referência não determina, sozinha, o ciclo de vida dos objetos relacionados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.4, páginas 1312–1325 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3d43e118-cb19-5c0c-9f60-7ebb053c00b2', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Qual limitação pode surgir se apenas métodos predefinidos permitirem acesso aos objetos?', '["Proibição de objetos imutáveis.","Eliminação da necessidade de índices.","Impossibilidade de definir classes.","Garantia automática de toda consulta futura.","Dificuldade de formular consultas ad hoc não previstas."]'::jsonb, 4, 'A interface de operações precisa atender também a necessidades de consulta não antecipadas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.5, páginas 1326–1336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7e01df4d-e47c-5997-b2cd-0fde65e48bfc', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Implementar integridade somente em métodos escritos pela aplicação exige atenção a:', '["Correção do código e cobertura de todos os caminhos de atualização.","Somente a quantidade de letras do método.","Apenas o nome da classe.","Exclusivamente a ordem dos arquivos.","A ausência de qualquer regra."]'::jsonb, 0, 'Um caminho que contorne a validação pode permitir estado inválido.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.5, páginas 1326–1336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d13b1d2c-ecdc-5346-9675-a6ccd9fb363a', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Manter referências nos dois sentidos entre objetos exige:', '["Confirmar cada campo separadamente.","Ignorar uma das direções.","Criar identidades iguais para todos os objetos.","Eliminar todos os métodos.","Coordenar alterações para preservar sua consistência."]'::jsonb, 4, 'Referências inversas não devem divergir quando a associação muda.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.5, páginas 1326–1336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d653999f-24d6-52ed-9636-8b60f7f54b42', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'Coleta de lixo de objetos inalcançáveis equivale a implementar todas as regras de integridade referencial do negócio?', '["Sim, se houver uma classe raiz.","Não, porque coleta de lixo nunca remove objetos.","Não; a política de alcançabilidade não cobre necessariamente essas regras.","Sim, desde que não existam índices.","Sim, são conceitos idênticos."]'::jsonb, 2, 'Gerenciar memória ou persistência por referências não substitui a semântica de exclusão exigida pelo domínio.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.5, páginas 1326–1336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f1cd8cd4-6f80-573b-9bb2-d18668623169', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'Uma linguagem unificada para programa e banco busca reduzir:', '["A necessidade de qualquer tipo.","A possibilidade de usar consultas.","A existência de dados persistentes.","O descasamento entre os modelos e formas de acesso usados nessas camadas.","A necessidade de regras de negócio."]'::jsonb, 3, 'A integração pode reduzir conversões conceituais, sem eliminar os demais requisitos de um SGBD.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.5, páginas 1326–1336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('15d1550e-209a-5337-b188-053e2e1e6e7a', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Qual avaliação respeita a análise crítica de Date sobre sistemas de objetos?', '["Métodos substituem a necessidade de dados.","Persistência dispensa recuperação.","Tipos, operadores e encapsulamento são úteis, mas não dispensam integridade e consultas adequadas.","Identidade resolve automaticamente qualquer restrição.","Objetos tornam toda consulta ad hoc desnecessária."]'::jsonb, 2, 'O capítulo examina tanto recursos úteis quanto insuficiências de certas abordagens.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.5, páginas 1326–1336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
